def transform(grid):
    """Recover rectangular outlined panels, then fill their interiors with
    the two least-common non-panel marker colors in alternating checkerboards.
    Exterior clutter is erased.
    """
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    seen = set()
    panels = []

    # Locate monochrome connected components that exactly form a hollow rectangle.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            r0 = min(rr for rr, _ in cells)
            r1 = max(rr for rr, _ in cells)
            c0 = min(cc for _, cc in cells)
            c1 = max(cc for _, cc in cells)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            border = {
                (rr, cc)
                for rr in range(r0, r1 + 1)
                for cc in range(c0, c1 + 1)
                if rr in (r0, r1) or cc in (c0, c1)
            }
            if set(cells) == border:
                panels.append((r0, c0, r1, c1, color))

    if not panels:
        return out
    panels.sort(key=lambda p: (p[0], p[1]))
    panel_cells = {
        (r, c)
        for r0, c0, r1, c1, _ in panels
        for r in range(r0, r1 + 1)
        for c in range(c0, c1 + 1)
        if r in (r0, r1) or c in (c0, c1)
    }
    counts = Counter(
        grid[r][c]
        for r in range(h)
        for c in range(w)
        if grid[r][c] != 0 and (r, c) not in panel_cells
    )
    # Sparse colored markers encode the panel fills; frequent distractor specks
    # are ignored. The two marker colors map in frequency order to panels.
    marker_colors = [color for color, _ in sorted(counts.items(), key=lambda kv: (kv[1], kv[0]))[:len(panels)]]

    for i, (r0, c0, r1, c1, border_color) in enumerate(panels):
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
